(() => {
'use strict';
const $ = q => document.querySelector(q), $$ = q => [...document.querySelectorAll(q)];
const params = new URLSearchParams(location.search), watchId = params.get('watch');
const uid = () => crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
const now = () => Date.now();

const I18N = {
 tr:{ready:'Hazır',live:'Yayında',connecting:'Bağlanıyor',waiting:'Yayıncı onayı bekleniyor',admitted:'Katılım onaylandı',rejected:'Katılım reddedildi',locked:'Yayın kilitli',viewer:'İzleyici',speaker:'Konuşmacı',moderator:'Moderatör',raise:'✋ Söz İste',cancelHand:'✋ İsteği Geri Çek',micOpen:'🎙 Mikrofonu Aç',micClose:'🔇 Mikrofonu Kapat',camOpen:'📹 Kamerayı Aç',camClose:'📷 Kamerayı Kapat',chatPlaceholder:'Mesaj yaz…',send:'Gönder',fullscreen:'⛶ Tam ekran',chat:'💬 Sohbet',joined:'yayına bağlandı',hand:'söz istiyor',good:'İyi',mid:'Orta',bad:'Zayıf'},
 en:{ready:'Ready',live:'Live',connecting:'Connecting',waiting:'Waiting for host approval',admitted:'Admission approved',rejected:'Admission rejected',locked:'Room locked',viewer:'Viewer',speaker:'Speaker',moderator:'Moderator',raise:'✋ Raise Hand',cancelHand:'✋ Cancel Request',micOpen:'🎙 Turn Mic On',micClose:'🔇 Turn Mic Off',camOpen:'📹 Turn Camera On',camClose:'📷 Turn Camera Off',chatPlaceholder:'Write a message…',send:'Send',fullscreen:'⛶ Full screen',chat:'💬 Chat',joined:'joined the broadcast',hand:'raised a hand',good:'Good',mid:'Medium',bad:'Poor'}
};

const state = {
 peer:null, source:'screen', localStream:null, rawStreams:[], audioContexts:[], calls:new Map(), dataConnections:new Map(), participants:new Map(), blockedPeers:new Set(), notifiedPeers:new Set(), viewerAudioEls:new Map(), analysers:new Map(),
 settings:{pin:'',waitingRoom:true,locked:false}, startedAt:0, timer:null, qualityTimer:null, renderTimer:null,
 stats:{total:0,max:0,messages:0,hands:0}, moderationLog:[], chatMessages:[], reactionVoters:new Map(), pinnedMessageId:null, hostReplyTo:null, poll:null, pollVoters:new Map(),
 recording:null, recordChunks:[], paused:false, pauseMedia:null, currentBroadcastStream:null, stagePeerId:null, stageComposite:null, screenStream:null, screenVideoEl:null,
 lang:localStorage.getItem('ebs-lang') || 'tr', theme:localStorage.getItem('ebs-theme') || 'dark',
 viewer:{name:'',pin:'',role:'viewer',data:null,call:null,offer:null,micStream:null,camStream:null,micAllowed:false,camAllowed:false,hand:false,admitted:false,connectedAt:0,replyTo:null,pollVoted:null,quality:'—',qualityDetail:'',modSnapshot:[]}
};

const homeView=$('#homeView'), studioView=$('#studioView'), viewerView=$('#viewerView'), features=$('#features'), localVideo=$('#localVideo'), remoteVideo=$('#remoteVideo'), shareLink=$('#shareLink');
$('#year').textContent=new Date().getFullYear();

function t(k){ return I18N[state.lang]?.[k] || I18N.tr[k] || k; }
function showToast(msg){const el=$('#toast'); if(!el)return; el.textContent=msg; el.classList.add('show'); clearTimeout(showToast._t); showToast._t=setTimeout(()=>el.classList.remove('show'),2400);}
function setNetwork(text,ok=true){$('#networkText').textContent=text; const dot=$('.status-pill i'); if(dot)dot.style.background=ok?'var(--green)':'var(--red)';}
function fmtTime(ms){const s=Math.max(0,Math.floor(ms/1000)); return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function formatClock(ts){return new Date(ts).toLocaleTimeString(state.lang==='en'?'en-US':'tr-TR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function normalizeText(v,max=500){return String(v??'').normalize('NFKC').replace(/[\u0000-\u001F\u007F]/g,'').trim().slice(0,max);}
const SECURITY_RE=/(?:<|>|\bscript\b|\bxss\b|javascript\s*:|vbscript\s*:|data\s*:\s*text\/html|on(?:error|load|click|mouseover|focus|input|change|submit|animationstart)\s*=|\beval\s*\(|document\.(?:cookie|write)|window\.location|srcdoc\s*=|expression\s*\()/i;
function isSuspicious(v){return SECURITY_RE.test(String(v??''));}
function safeName(v){const x=normalizeText(v,32).replace(/\s{2,}/g,' '); return x.length>=2&&!isSuspicious(x)?x:null;}
function safePin(v){const x=String(v??'').trim(); return x===''?'':(/^\d{4,8}$/.test(x)?x:null);}
function participantLabel(id){const p=state.participants.get(id); return p?.name || `Misafir ${String(id||'').slice(-4).toUpperCase()}`;}
function roleLabel(r){return r==='moderator'?t('moderator'):r==='speaker'?t('speaker'):t('viewer');}
function qualityClass(q){return q==='good'?'quality-good':q==='mid'?'quality-mid':q==='bad'?'quality-bad':'';}
function qualityLabel(q){return q==='good'?t('good'):q==='mid'?t('mid'):q==='bad'?t('bad'):'—';}
function formatBytes(n){return n<1024?`${n} B`:n<1048576?`${(n/1024).toFixed(1)} KB`:`${(n/1048576).toFixed(1)} MB`;}

function applyTheme(){document.body.dataset.theme=state.theme; $('#themeBtn').textContent=state.theme==='dark'?'☀️':'🌙';}
function applyLanguage(){document.documentElement.lang=state.lang; $('#globalLang').value=state.lang; $('#networkText').textContent=studioView.classList.contains('hidden')?t('ready'):t('live'); $('#raiseHandBtn').textContent=state.viewer.hand?t('cancelHand'):t('raise'); $('#viewerMicBtn').textContent=state.viewer.micStream?.getAudioTracks?.()[0]?.enabled?t('micClose'):t('micOpen'); $('#viewerCameraBtn').textContent=state.viewer.camStream?.getVideoTracks?.()[0]?.enabled?t('camClose'):t('camOpen'); $('#viewerChatInput').placeholder=t('chatPlaceholder'); $('#hostChatInput').placeholder=t('chatPlaceholder'); $('#fullscreenBtn').textContent=t('fullscreen'); $('#mobileChatBtn').textContent=t('chat'); $('#viewerRoleBadge').textContent=roleLabel(state.viewer.role); renderParticipants(); renderChatAll(); renderPollAll();}
applyTheme(); applyLanguage();
$('#themeBtn').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark'; localStorage.setItem('ebs-theme',state.theme); applyTheme();});
$('#globalLang').addEventListener('change',e=>{state.lang=e.target.value==='en'?'en':'tr'; localStorage.setItem('ebs-lang',state.lang); applyLanguage();});

$$('.share-option').forEach(btn=>btn.addEventListener('click',()=>{$$('.share-option').forEach(x=>x.classList.remove('active'));btn.classList.add('active');state.source=btn.dataset.source;$('#cameraOverlayToggle').disabled=state.source!=='screen';$('#cameraOverlayRow').style.opacity=state.source==='screen'?'1':'.4';}));

async function getMic(){if(!$('#micToggle').checked)return null; return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});}
async function mixTracks(tracks,key='general'){const live=tracks.filter(x=>x&&x.readyState==='live'); if(!live.length)return null; if(live.length===1)return live[0]; const AC=window.AudioContext||window.webkitAudioContext; if(!AC)return live[0]; const ctx=new AC(); state.audioContexts.push(ctx); const dest=ctx.createMediaStreamDestination(); live.forEach(track=>{try{ctx.createMediaStreamSource(new MediaStream([track])).connect(dest);}catch{}}); return dest.stream.getAudioTracks()[0]||live[0];}
async function buildScreenStream(){const display=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:{ideal:30,max:60}},audio:true});state.rawStreams.push(display);state.screenStream=display;const mic=await getMic();if(mic)state.rawStreams.push(mic);if($('#cameraOverlayToggle').checked){const cam=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false});state.rawStreams.push(cam);return composeHost(display,cam,mic);}const out=new MediaStream();display.getVideoTracks().forEach(x=>out.addTrack(x));const a=await mixTracks([...display.getAudioTracks(),...(mic?mic.getAudioTracks():[])]);if(a)out.addTrack(a);return out;}
async function buildCameraStream(){const cam=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1920},height:{ideal:1080},frameRate:{ideal:30},facingMode:'user'},audio:$('#micToggle').checked?{echoCancellation:true,noiseSuppression:true,autoGainControl:true}:false});state.rawStreams.push(cam);return cam;}
async function composeHost(screen,camera,mic){const sv=document.createElement('video'),cv=document.createElement('video');sv.srcObject=screen;cv.srcObject=camera;sv.muted=cv.muted=true;await Promise.allSettled([sv.play(),cv.play()]);state.screenVideoEl=sv;state.screenStream=screen;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{alpha:false});canvas.width=1920;canvas.height=1080;let run=true;const draw=()=>{if(!run)return;const sw=sv.videoWidth||1920,sh=sv.videoHeight||1080,scale=Math.min(canvas.width/sw,canvas.height/sh),dw=sw*scale,dh=sh*scale;ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(sv,(canvas.width-dw)/2,(canvas.height-dh)/2,dw,dh);const cw=360,ch=cw*((cv.videoHeight||720)/(cv.videoWidth||1280)),x=canvas.width-cw-40,y=canvas.height-ch-40;ctx.drawImage(cv,x,y,cw,ch);requestAnimationFrame(draw)};draw();state.rawStreams.push(canvas.captureStream(30));const out=canvas.captureStream(30),a=await mixTracks([...screen.getAudioTracks(),...(mic?mic.getAudioTracks():[])]);if(a)out.addTrack(a);out._stopCompositor=()=>{run=false;};return out;}

function cleanViewerUrl(id){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('watch',id);return u.toString();}
async function copyLink(){const value=shareLink.value;if(!value||value.includes('hazırlanıyor'))return;try{await navigator.clipboard.writeText(value);}catch{shareLink.select();document.execCommand('copy');}showToast('Bağlantı kopyalandı');}
function renderQR(url){const el=$('#qrCode');el.textContent=''; if(!url||!window.QRCode)return; new QRCode(el,{text:url,width:80,height:80,correctLevel:QRCode.CorrectLevel.M});}

async function startBroadcast(){if(!navigator.mediaDevices||!window.Peer){showToast('WebRTC desteklenmiyor.');return;}const pin=safePin($('#roomPinInput').value);if(pin===null){showToast('PIN 4-8 rakam olmalı.');return;}state.settings.pin=pin;state.settings.waitingRoom=$('#waitingRoomToggle').checked;const btn=$('#startBtn');btn.disabled=true;try{state.localStream=state.source==='screen'?await buildScreenStream():await buildCameraStream();state.currentBroadcastStream=state.localStream;const vt=state.localStream.getVideoTracks()[0];vt?.addEventListener('ended',stopBroadcast);localVideo.srcObject=state.localStream;await localVideo.play().catch(()=>{});$('#stageEmpty').classList.add('hidden');$('#sourceBadge').textContent=state.source==='screen'?'EKRAN':'KAMERA';$('#switchScreenBtn')?.classList.toggle('hidden',state.source!=='screen');homeView.classList.add('hidden');features.classList.add('hidden');studioView.classList.remove('hidden');state.startedAt=now();startTimers();initHostPeer();logMod('Yayın başlatıldı');updateSecurityText();}catch(err){console.error(err);showToast(err.name==='NotAllowedError'?'Ekran/kamera izni verilmedi.':'Yayın başlatılamadı.');btn.disabled=false;cleanupAllMedia();}}

function initHostPeer(){setNetwork('Bağlantı kuruluyor');state.peer=new Peer(undefined,{debug:1});state.peer.on('open',id=>{const url=cleanViewerUrl(id);shareLink.value=url;renderQR(url);setNetwork(t('live'));showToast('Yayın hazır');});state.peer.on('connection',handleHostDataConnection);state.peer.on('call',call=>{const p=state.participants.get(call.peer);if(!p?.admitted||state.blockedPeers.has(call.peer)){call.close();return;}call.answer(state.currentBroadcastStream||state.localStream);state.calls.set(call.peer,call);p.mediaConnected=true;updateStats();renderParticipants();call.on('stream',stream=>attachViewerMedia(call.peer,stream));call.on('close',()=>disconnectMedia(call.peer));call.on('error',()=>disconnectMedia(call.peer));});state.peer.on('error',err=>{console.error(err);setNetwork('Bağlantı hatası',false);showToast(`P2P hata: ${err.type||'network'}`);});}

function ensureParticipant(id){if(!state.participants.has(id))state.participants.set(id,{peerId:id,name:'',role:'viewer',admitted:false,waiting:false,raisedHand:false,handAt:0,micAllowed:false,camAllowed:false,speaking:false,cameraOn:false,connectedAt:0,quality:'—',qualityDetail:'',mutedUntil:0,spamStrikes:0,messageTimes:[],reactionTimes:[],remoteStream:null,mediaConnected:false,lastBytes:0,lastBytesAt:0});return state.participants.get(id);}
function updateStats(){const current=[...state.participants.values()].filter(p=>p.admitted).length;state.stats.max=Math.max(state.stats.max,current);$('#viewerCount').textContent=current;$('#statCurrent').textContent=current;$('#statTotal').textContent=state.stats.total;$('#statMax').textContent=state.stats.max;$('#statMessages').textContent=state.stats.messages;$('#statHands').textContent=state.stats.hands;}
function updateSecurityText(){$('#roomSecurityText').textContent=`${state.settings.waitingRoom?'Bekleme odası açık':'Doğrudan giriş'}${state.settings.pin?' • PIN aktif':''}${state.settings.locked?' • KİLİTLİ':''}`;$('#lockBtn').textContent=state.settings.locked?'🔒 Kilitli':'🔓 Açık';}

function handleHostDataConnection(conn){state.dataConnections.set(conn.peer,conn);const p=ensureParticipant(conn.peer);conn.on('open',()=>{if(state.blockedPeers.has(conn.peer)){conn.close();return;}conn.send({type:'host-ready',requiresPin:!!state.settings.pin,waitingRoom:state.settings.waitingRoom,locked:state.settings.locked,lang:state.lang});});conn.on('data',data=>handleHostData(conn,data));conn.on('close',()=>disconnectData(conn.peer));conn.on('error',()=>disconnectData(conn.peer));}
function handleHostData(conn,data){if(!data||typeof data!=='object'||state.blockedPeers.has(conn.peer))return;const p=ensureParticipant(conn.peer);
 if(data.type==='hello'){const name=safeName(data.name),pin=String(data.pin??'');if(!name){securityKick(conn.peer,'Şüpheli/geçersiz kullanıcı adı');return;}if(state.settings.locked){conn.send({type:'rejected',reason:'Yayın yeni katılımcılara kilitli.'});setTimeout(()=>conn.close(),100);return;}if(state.settings.pin&&pin!==state.settings.pin){conn.send({type:'rejected',reason:'Oda PIN’i hatalı.'});logMod(`${name}: hatalı PIN`);setTimeout(()=>conn.close(),200);return;}p.name=name;p.waiting=state.settings.waitingRoom;renderWaiting();if(state.settings.waitingRoom){conn.send({type:'lobby-pending'});showHostNotice('🚪 Bekleme odası',`${name} katılmak istiyor`);beep();browserNotify('Katılma isteği',`${name} bekleme odasında`);logMod(`${name} bekleme odasına geldi`);}else approveAdmission(conn.peer,'system');
 } else if(!p.admitted){return;
 } else if(data.type==='raise-hand'){p.raisedHand=true;p.handAt=now();state.stats.hands++;renderSpeakerQueue();renderParticipants();updateStats();showHostNotice('✋ Söz isteği',`${p.name} söz istiyor`);beep();browserNotify('Söz isteği',`${p.name} söz istiyor`);logMod(`${p.name} söz istedi`);broadcastModSnapshots();
 } else if(data.type==='cancel-hand'){p.raisedHand=false;p.handAt=0;renderSpeakerQueue();renderParticipants();broadcastModSnapshots();
 } else if(data.type==='mic-enabled'){p.speaking=true;renderParticipants();logMod(`${p.name} mikrofonunu açtı`);broadcastModSnapshots();
 } else if(data.type==='mic-disabled'){p.speaking=false;renderParticipants();broadcastModSnapshots();
 } else if(data.type==='camera-enabled'){p.cameraOn=true;renderParticipants();broadcastModSnapshots();if(state.stagePeerId===p.peerId)refreshStageComposite();
 } else if(data.type==='camera-disabled'){p.cameraOn=false;if(state.stagePeerId===p.peerId)removeFromStage(p.peerId);renderParticipants();broadcastModSnapshots();
 } else if(data.type==='chat'){handleIncomingChat(p,data);
 } else if(data.type==='file'){handleIncomingFile(p,data);
 } else if(data.type==='message-react'){handleMessageReaction(p.peerId,data.messageId,data.emoji);
 } else if(data.type==='live-reaction'){handleLiveReaction(p,data.emoji);
 } else if(data.type==='poll-vote'){handlePollVote(p,data.pollId,Number(data.option));
 } else if(data.type==='moderation'){handleModeratorCommand(p,data);
 }}

function approveAdmission(id,actor='host'){const p=state.participants.get(id),conn=state.dataConnections.get(id);if(!p||!conn?.open)return;p.admitted=true;p.waiting=false;p.connectedAt=now();state.stats.total++;conn.send({type:'admitted',role:p.role,history:publicHistory(),pinnedId:state.pinnedMessageId,poll:publicPoll()});notifyJoinedOnce(id);logMod(`${p.name} kabul edildi${actor==='system'?' (otomatik)':''}`);renderWaiting();renderParticipants();updateStats();broadcastModSnapshots();}
function rejectAdmission(id){const p=state.participants.get(id),conn=state.dataConnections.get(id);if(!p)return;conn?.send({type:'rejected',reason:'Yayıncı katılma isteğini reddetti.'});logMod(`${p.name||participantLabel(id)} reddedildi`);setTimeout(()=>conn?.close(),120);state.participants.delete(id);renderWaiting();renderParticipants();}
function notifyJoinedOnce(id){if(state.notifiedPeers.has(id))return;state.notifiedPeers.add(id);const name=participantLabel(id);showHostNotice('👋 Yeni katılımcı',`${name} ${t('joined')}`);beep();browserNotify('Yeni katılımcı',`${name} ${t('joined')}`);}
function disconnectData(id){state.dataConnections.delete(id);const p=state.participants.get(id);if(p&&!state.calls.has(id)){if(p.admitted)logMod(`${p.name} ayrıldı`);state.participants.delete(id);}renderWaiting();renderParticipants();renderSpeakerQueue();updateStats();broadcastModSnapshots();}
function disconnectMedia(id){state.calls.delete(id);const p=state.participants.get(id);if(p){p.mediaConnected=false;p.speaking=false;p.cameraOn=false;}removeViewerMedia(id);if(state.stagePeerId===id)removeFromStage(id);renderParticipants();updateStats();}

function showHostNotice(title,detail,danger=false){if(studioView.classList.contains('hidden'))return;const stack=$('#hostNoticeStack'),el=document.createElement('div'),strong=document.createElement('strong'),span=document.createElement('span');el.className=`join-notice${danger?' security-badge':''}`;strong.textContent=title;span.textContent=detail;el.append(strong,span);stack.appendChild(el);setTimeout(()=>el.remove(),4600);}
function beep(){try{const AC=window.AudioContext||window.webkitAudioContext,ctx=new AC(),osc=ctx.createOscillator(),gain=ctx.createGain();gain.gain.value=.035;osc.frequency.value=720;osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.09);setTimeout(()=>ctx.close(),300);}catch{}}
function browserNotify(title,body){if(document.hidden&&'Notification' in window&&Notification.permission==='granted')new Notification(title,{body,icon:'assets/img/logo.png'});}
$('#notifyBtn').addEventListener('click',async()=>{if(!('Notification'in window)){showToast('Tarayıcı bildirimi desteklenmiyor.');return;}const p=await Notification.requestPermission();showToast(p==='granted'?'Tarayıcı bildirimleri açık.':'Bildirim izni verilmedi.');});

function logMod(text){state.moderationLog.unshift({time:now(),text:normalizeText(text,220)});state.moderationLog=state.moderationLog.slice(0,160);renderModLog();}
function renderModLog(){const box=$('#moderationLog');if(!box)return;box.textContent='';if(!state.moderationLog.length){const x=document.createElement('div');x.className='muted';x.textContent='Henüz olay yok.';box.append(x);return;}state.moderationLog.forEach(item=>{const row=document.createElement('div'),tm=document.createElement('time');row.className='log-item';tm.textContent=formatClock(item.time);row.append(tm,document.createTextNode(item.text));box.append(row);});}
$('#clearLogBtn').addEventListener('click',()=>{state.moderationLog=[];renderModLog();});

function renderWaiting(){const list=$('#waitingList'),arr=[...state.participants.values()].filter(p=>p.waiting&&!p.admitted);$('#waitingCount').textContent=arr.length;list.textContent='';if(!arr.length){const e=document.createElement('div');e.className='participants-empty';e.textContent='Bekleyen katılımcı yok.';list.append(e);return;}arr.forEach(p=>{const row=document.createElement('div');row.className='participant-row';row.innerHTML='<div class="participant-avatar">?</div><div class="participant-meta"></div><div class="participant-actions"></div>';row.querySelector('.participant-avatar').textContent=p.name.slice(0,2).toUpperCase();const meta=row.querySelector('.participant-meta');const b=document.createElement('b'),s=document.createElement('span');b.textContent=p.name;s.className='participant-status raised';s.textContent='Onay bekliyor';meta.append(b,s);const acts=row.querySelector('.participant-actions');acts.append(actionBtn('✓ Kabul','approve-wait',p.peerId,'approve'),actionBtn('✕ Reddet','reject-wait',p.peerId,'danger-soft'));list.append(row);});}
function renderSpeakerQueue(){const box=$('#speakerQueue'),arr=[...state.participants.values()].filter(p=>p.admitted&&p.raisedHand).sort((a,b)=>a.handAt-b.handAt);$('#queueCount').textContent=arr.length;box.textContent='';if(!arr.length){const e=document.createElement('div');e.className='participants-empty';e.textContent='Söz isteyen yok.';box.append(e);return;}arr.forEach((p,i)=>{const row=document.createElement('div');row.className='queue-item';const left=document.createElement('div'),rank=document.createElement('span'),name=document.createElement('b');left.style.display='flex';left.style.alignItems='center';left.style.gap='10px';rank.className='queue-rank';rank.textContent=i+1;name.textContent=`${p.name} • ${fmtTime(now()-p.handAt)}`;left.append(rank,name);row.append(left,actionBtn('🎙 Söz Ver','approve-mic',p.peerId,'approve'));box.append(row);});}
function actionBtn(label,action,peer,cls=''){const b=document.createElement('button');b.type='button';b.className=`participant-btn ${cls}`;b.dataset.action=action;b.dataset.peer=peer;b.textContent=label;return b;}

function renderParticipants(){const list=$('#participantsList');if(!list)return;const arr=[...state.participants.values()].filter(p=>p.admitted);list.textContent='';if(!arr.length){const e=document.createElement('div');e.className='participants-empty';e.textContent='Henüz bağlı izleyici yok.';list.append(e);return;}arr.sort((a,b)=>(b.speaking-a.speaking)||(b.raisedHand-a.raisedHand)||a.connectedAt-b.connectedAt).forEach(p=>{const row=document.createElement('div');row.className=`participant-row${p.audioActive?' active-speaker':''}`;const avatar=document.createElement('div');avatar.className='participant-avatar';avatar.textContent=(p.name||'??').slice(0,2).toUpperCase();const meta=document.createElement('div');meta.className='participant-meta';const b=document.createElement('b'),st=document.createElement('span'),sub=document.createElement('span');b.textContent=p.name;st.className=`participant-status ${p.speaking?'speaking':p.raisedHand?'raised':''}`;st.textContent=p.speaking?'🎙 Konuşuyor':p.raisedHand?'✋ Söz istiyor':'👁 İzliyor';sub.className=`subline ${qualityClass(p.quality)}`;sub.textContent=`${roleLabel(p.role)} • ${fmtTime(now()-p.connectedAt)} • 📶 ${qualityLabel(p.quality)}${p.qualityDetail?` (${p.qualityDetail})`:''}`;meta.append(b,st,sub);const acts=document.createElement('div');acts.className='participant-actions';const sel=document.createElement('select');sel.className='role-select';sel.dataset.action='role';sel.dataset.peer=p.peerId;[['viewer','İzleyici'],['speaker','Konuşmacı'],['moderator','Moderatör']].forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;o.selected=p.role===v;sel.append(o);});acts.append(sel);if(p.speaking||p.micAllowed)acts.append(actionBtn('🔇 Sustur','mute',p.peerId,'danger-soft'));else acts.append(actionBtn('🎙 Ses İzni','approve-mic',p.peerId,'approve'));if(p.cameraOn){acts.append(state.stagePeerId===p.peerId?actionBtn('↙ Sahne Dışı','unstage',p.peerId):actionBtn('🖥 Sahneye Al','stage',p.peerId,'approve'));}else acts.append(actionBtn('📹 Kamera İzni','approve-camera',p.peerId));acts.append(actionBtn('⛔ Çıkar','kick',p.peerId,'danger-soft'));row.append(avatar,meta,acts);list.append(row);});}

function setRole(id,role){if(!['viewer','speaker','moderator'].includes(role))return;const p=state.participants.get(id);if(!p)return;p.role=role;if(role==='speaker')approveMic(id);state.dataConnections.get(id)?.send({type:'role',role});logMod(`${p.name} rolü: ${roleLabel(role)}`);renderParticipants();broadcastModSnapshots();}
function approveMic(id){const p=state.participants.get(id);if(!p)return;p.micAllowed=true;p.raisedHand=false;p.handAt=0;state.dataConnections.get(id)?.send({type:'mic-approved'});logMod(`${p.name} için mikrofon izni verildi`);renderSpeakerQueue();renderParticipants();broadcastModSnapshots();}
function muteParticipant(id,actor='Yayıncı'){const p=state.participants.get(id);if(!p)return;p.speaking=false;p.micAllowed=false;state.dataConnections.get(id)?.send({type:'mic-disable'});logMod(`${p.name} ${actor} tarafından susturuldu`);renderParticipants();broadcastModSnapshots();}
function approveCamera(id){const p=state.participants.get(id);if(!p)return;p.camAllowed=true;state.dataConnections.get(id)?.send({type:'camera-approved'});logMod(`${p.name} için kamera izni verildi`);renderParticipants();}
function securityKick(id,reason){state.blockedPeers.add(id);kickParticipant(id,reason,true);}
function kickParticipant(id,reason='Yayıncı tarafından çıkarıldı',security=false){const p=state.participants.get(id),name=p?.name||participantLabel(id),conn=state.dataConnections.get(id);try{conn?.send({type:'kicked',reason});}catch{}state.calls.get(id)?.close();setTimeout(()=>conn?.close(),100);removeViewerMedia(id);state.calls.delete(id);state.dataConnections.delete(id);state.participants.delete(id);if(state.stagePeerId===id)removeFromStage(id);renderWaiting();renderParticipants();renderSpeakerQueue();updateStats();showHostNotice(security?'🛡️ Güvenlik engeli':'⛔ Katılımcı çıkarıldı',`${name} — ${reason}`,security);logMod(`${name} çıkarıldı: ${reason}`);broadcastModSnapshots();}

function attachViewerMedia(id,stream){const p=ensureParticipant(id);p.remoteStream=stream;removeViewerMedia(id);const audio=document.createElement('audio');audio.className='viewer-return-audio';audio.autoplay=true;audio.srcObject=stream;document.body.append(audio);audio.play().catch(()=>{});state.viewerAudioEls.set(id,audio);setupAnalyser(id,stream);if(state.stagePeerId===id){$('#guestPreview').srcObject=stream;$('#guestPreview').classList.remove('hidden');refreshStageComposite();}}
function removeViewerMedia(id){state.viewerAudioEls.get(id)?.remove();state.viewerAudioEls.delete(id);const a=state.analysers.get(id);if(a){a.ctx.close().catch(()=>{});state.analysers.delete(id);}}
function setupAnalyser(id,stream){try{const AC=window.AudioContext||window.webkitAudioContext,ctx=new AC(),an=ctx.createAnalyser();an.fftSize=256;ctx.createMediaStreamSource(stream).connect(an);state.analysers.set(id,{ctx,an,data:new Uint8Array(an.frequencyBinCount)});}catch{}}
function pollAudioLevels(){let changed=false;state.analysers.forEach((o,id)=>{const p=state.participants.get(id);if(!p)return;o.an.getByteFrequencyData(o.data);const avg=o.data.reduce((a,b)=>a+b,0)/o.data.length;const active=avg>18&&p.speaking;if(active!==p.audioActive){p.audioActive=active;changed=true;}});if(changed)renderParticipants();}

async function buildStageComposite(p){stopStageComposite();if(!p?.remoteStream)return null;const guest=$('#guestPreview');guest.srcObject=p.remoteStream;guest.classList.remove('hidden');await guest.play().catch(()=>{});const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{alpha:false});canvas.width=1280;canvas.height=720;let running=true;const draw=()=>{if(!running)return;ctx.fillStyle='#000';ctx.fillRect(0,0,1280,720);drawCover(ctx,localVideo,0,0,1280,720);const gw=380,gh=214,x=1280-gw-28,y=720-gh-28;ctx.fillStyle='#fff';roundRect(ctx,x-5,y-5,gw+10,gh+10,18);ctx.fill();ctx.save();roundRect(ctx,x,y,gw,gh,14);ctx.clip();drawCover(ctx,guest,x,y,gw,gh);ctx.restore();requestAnimationFrame(draw);};draw();const out=canvas.captureStream(30);const mixed=await mixTracks([...state.localStream.getAudioTracks(),...p.remoteStream.getAudioTracks()],'stage');if(mixed)out.addTrack(mixed);state.stageComposite={canvas,stream:out,stop:()=>{running=false;out.getVideoTracks().forEach(x=>x.stop());}};return out;}
function drawCover(ctx,video,x,y,w,h){const vw=video.videoWidth||w,vh=video.videoHeight||h,scale=Math.max(w/vw,h/vh),dw=vw*scale,dh=vh*scale;try{ctx.drawImage(video,x+(w-dw)/2,y+(h-dh)/2,dw,dh);}catch{}}
function roundRect(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,w,h,r):ctx.rect(x,y,w,h);}
async function stageParticipant(id){const p=state.participants.get(id);if(!p?.cameraOn||!p.remoteStream){showToast('Önce katılımcı kamerasını açmalı.');return;}state.stagePeerId=id;const composite=await buildStageComposite(p);if(!composite)return;state.currentBroadcastStream=composite;await applyOutgoingStreams(composite,id);state.dataConnections.forEach(c=>c.open&&c.send({type:'stage-state',name:p.name,active:true}));logMod(`${p.name} sahneye alındı`);renderParticipants();}
async function refreshStageComposite(){if(!state.stagePeerId)return;const p=state.participants.get(state.stagePeerId);if(p?.cameraOn)await stageParticipant(p.peerId);}
async function removeFromStage(id){if(state.stagePeerId!==id)return;const p=state.participants.get(id);state.stagePeerId=null;stopStageComposite();$('#guestPreview').classList.add('hidden');$('#guestPreview').srcObject=null;state.currentBroadcastStream=state.localStream;await applyOutgoingStreams(state.localStream,null);state.dataConnections.forEach(c=>c.open&&c.send({type:'stage-state',active:false}));if(p)logMod(`${p.name} sahneden çıkarıldı`);renderParticipants();}
function stopStageComposite(){state.stageComposite?.stop?.();state.stageComposite=null;}
async function applyOutgoingStreams(stream,guestId=null){const video=stream?.getVideoTracks?.()[0],audio=stream?.getAudioTracks?.()[0],hostAudio=state.localStream?.getAudioTracks?.()[0];for(const [id,call] of state.calls){const senders=call.peerConnection?.getSenders?.()||[];const vs=senders.find(s=>s.track?.kind==='video');const as=senders.find(s=>s.track?.kind==='audio');if(vs&&video)await vs.replaceTrack(video).catch(()=>{});if(as){const a=id===guestId?(hostAudio||audio):audio;if(a)await as.replaceTrack(a).catch(()=>{});}}}

function spamCheck(p){const ts=now();p.messageTimes=p.messageTimes.filter(x=>ts-x<3000);p.messageTimes.push(ts);if(ts<p.mutedUntil)return false;if(p.messageTimes.length>=10){p.spamStrikes++;p.mutedUntil=ts+30000;state.dataConnections.get(p.peerId)?.send({type:'temp-muted',until:p.mutedUntil});logMod(`${p.name} anti-spam nedeniyle 30 sn susturuldu`);if(p.spamStrikes>=2){kickParticipant(p.peerId,'Tekrarlanan spam');}return false;}return true;}
const ALLOWED_FILE_TYPES=new Set(['image/jpeg','image/png','image/gif','image/webp','application/pdf','text/plain','application/zip','application/x-zip-compressed']);const ALLOWED_FILE_EXT=new Set(['jpg','jpeg','png','gif','webp','pdf','txt','zip']);const MAX_FILE_BYTES=5*1024*1024;
function validFileMeta(name,size,mime,buffer){const ext=String(name||'').split('.').pop().toLowerCase();return name&&!isSuspicious(name)&&size>0&&size<=MAX_FILE_BYTES&&ALLOWED_FILE_EXT.has(ext)&&ALLOWED_FILE_TYPES.has(mime)&&buffer instanceof ArrayBuffer;}
function handleIncomingChat(p,data){if(!spamCheck(p))return;const text=normalizeText(data.text,500);if(!text)return;if(isSuspicious(text)){securityKick(p.peerId,'XSS/script kalıbı tespit edildi');return;}const reply=state.chatMessages.find(x=>x.id===data.replyTo&&!x.deleted);const item={id:uid(),type:'chat',sender:p.name,peerId:p.peerId,text,time:now(),replyTo:reply?.id||null,reactions:{}};addChatItem(item);}
function handleIncomingFile(p,data){if(!spamCheck(p))return;const name=normalizeText(data.name,80),size=Number(data.size||0),mime=normalizeText(data.mime,80);if(!validFileMeta(name,size,mime,data.buffer)){securityKick(p.peerId,'Güvensiz dosya gönderimi');return;}addChatItem({id:uid(),type:'file',sender:p.name,peerId:p.peerId,name,size,mime,buffer:data.buffer,time:now(),reactions:{}});}
function addChatItem(item){state.chatMessages.push(item);if(state.chatMessages.length>120)state.chatMessages.shift();state.stats.messages++;updateStats();broadcast({type:'chat-item',item:publicChatItem(item)});renderChatAll();}
function publicChatItem(x){return {...x,buffer:x.buffer instanceof ArrayBuffer?x.buffer:undefined};}
function publicHistory(){return state.chatMessages.slice(-100).map(publicChatItem);}
function broadcast(msg,onlyAdmitted=true){state.dataConnections.forEach((c,id)=>{const p=state.participants.get(id);if(c.open&&(!onlyAdmitted||p?.admitted)){try{c.send(msg);}catch{}}});}

function sendHostMessage(text){const value=normalizeText(text,500);if(!value)return;if(isSuspicious(value)){showToast('Şüpheli içerik engellendi.');return;}const reply=state.chatMessages.find(x=>x.id===state.hostReplyTo);addChatItem({id:uid(),type:'chat',sender:'Sunucu',peerId:'host',text:value,time:now(),replyTo:reply?.id||null,reactions:{}});state.hostReplyTo=null;renderReplyBars();}
async function sendFile(file,host){if(!file)return;const buffer=await file.arrayBuffer();if(!validFileMeta(normalizeText(file.name,80),file.size,file.type,buffer)){showToast('Dosya türü/boyutu güvenlik nedeniyle reddedildi.');return;}if(host)addChatItem({id:uid(),type:'file',sender:'Sunucu',peerId:'host',name:normalizeText(file.name,80),size:file.size,mime:file.type,buffer,time:now(),reactions:{}});else{if(!state.viewer.data?.open){showToast('Sohbet bağlantısı hazır değil.');return;}state.viewer.data.send({type:'file',name:normalizeText(file.name,80),size:file.size,mime:file.type,buffer});}}
function renderChatAll(){renderChat($('#hostChatMessages'),'host',true);renderChat($('#viewerChatMessages'),state.peer?.id||'',false);renderPinned();renderReplyBars();}
function renderChat(container,selfId,isHost){if(!container)return;container.textContent='';if(!state.chatMessages.length){const e=document.createElement('div');e.className='chat-empty';e.textContent='Henüz mesaj yok.';container.append(e);return;}state.chatMessages.filter(x=>!x.deleted).forEach(item=>container.append(buildMessage(item,selfId,isHost)));container.scrollTop=container.scrollHeight;}
function buildMessage(item,selfId,isHost){const row=document.createElement('div');row.className=`chat-message${item.peerId===selfId?' self':''}${(!isHost&&state.viewer.name&&item.text?.includes('@'+state.viewer.name))?' mention':''}`;row.dataset.messageId=item.id;const meta=document.createElement('div');meta.className='chat-meta';const b=document.createElement('b');b.textContent=item.sender;const tm=document.createElement('span');tm.textContent=new Date(item.time).toLocaleTimeString(state.lang==='en'?'en-US':'tr-TR',{hour:'2-digit',minute:'2-digit'});meta.append(b,tm);row.append(meta);if(item.replyTo){const ref=state.chatMessages.find(x=>x.id===item.replyTo);if(ref){const r=document.createElement('div');r.className='chat-reply';r.textContent=`↩ ${ref.sender}: ${ref.type==='chat'?ref.text.slice(0,80):ref.name}`;row.append(r);}}if(item.type==='chat'){const body=document.createElement('div');body.className='chat-body';body.textContent=item.text;row.append(body);}else{const a=document.createElement('a');a.href='#';a.className='chat-file';const txt=document.createElement('span');txt.textContent=`📎 ${item.name} (${formatBytes(item.size)})`;a.append(txt);a.addEventListener('click',e=>{e.preventDefault();if(!(item.buffer instanceof ArrayBuffer)){showToast('Dosya bu istemcide mevcut değil.');return;}const url=URL.createObjectURL(new Blob([item.buffer],{type:item.mime})),dl=document.createElement('a');dl.href=url;dl.download=item.name;dl.click();setTimeout(()=>URL.revokeObjectURL(url),20000);});row.append(a);}const tools=document.createElement('div');tools.className='chat-tools';['👍','❤️','😂','👏'].forEach(em=>{const bt=document.createElement('button');bt.type='button';bt.className='chat-tool';bt.textContent=`${em} ${item.reactions?.[em]||''}`;bt.dataset.msgAction='react';bt.dataset.messageId=item.id;bt.dataset.emoji=em;tools.append(bt);});const rep=document.createElement('button');rep.type='button';rep.className='chat-tool';rep.textContent='↩ Yanıtla';rep.dataset.msgAction='reply';rep.dataset.messageId=item.id;tools.append(rep);const men=document.createElement('button');men.type='button';men.className='chat-tool';men.textContent='@ Etiketle';men.dataset.msgAction='mention';men.dataset.messageId=item.id;tools.append(men);const canMod=isHost||state.viewer.role==='moderator';if(canMod){const pin=document.createElement('button');pin.type='button';pin.className='chat-tool';pin.textContent=state.pinnedMessageId===item.id?'📌 Sabit':'📌 Sabitle';pin.dataset.msgAction='pin';pin.dataset.messageId=item.id;const del=document.createElement('button');del.type='button';del.className='chat-tool';del.textContent='🗑 Sil';del.dataset.msgAction='delete';del.dataset.messageId=item.id;tools.append(pin,del);}row.append(tools);return row;}
function handleMessageReaction(peerId,messageId,emoji){if(!['👍','❤️','😂','👏'].includes(emoji))return;const item=state.chatMessages.find(x=>x.id===messageId&&!x.deleted);if(!item)return;let byMsg=state.reactionVoters.get(messageId);if(!byMsg){byMsg=new Map();state.reactionVoters.set(messageId,byMsg);}let set=byMsg.get(emoji);if(!set){set=new Set();byMsg.set(emoji,set);}if(set.has(peerId))set.delete(peerId);else set.add(peerId);item.reactions=item.reactions||{};item.reactions[emoji]=set.size;broadcast({type:'chat-update',item:publicChatItem(item)});renderChatAll();}
function deleteMessage(id,actor='Yayıncı'){const item=state.chatMessages.find(x=>x.id===id);if(!item)return;item.deleted=true;if(state.pinnedMessageId===id)state.pinnedMessageId=null;broadcast({type:'chat-delete',id});broadcast({type:'chat-pin',id:state.pinnedMessageId});logMod(`${actor} mesaj sildi (${item.sender})`);renderChatAll();}
function pinMessage(id,actor='Yayıncı'){const item=state.chatMessages.find(x=>x.id===id&&!x.deleted);if(!item)return;state.pinnedMessageId=state.pinnedMessageId===id?null:id;broadcast({type:'chat-pin',id:state.pinnedMessageId});logMod(`${actor} mesaj ${state.pinnedMessageId?'sabitledi':'sabitlemeyi kaldırdı'}`);renderPinned();renderChatAll();}
function renderPinned(){[['#hostPinned',true],['#viewerPinned',false]].forEach(([sel])=>{const box=$(sel),item=state.chatMessages.find(x=>x.id===state.pinnedMessageId&&!x.deleted);if(!box)return;if(!item){box.classList.add('hidden');box.textContent='';return;}box.classList.remove('hidden');box.textContent=`📌 ${item.sender}: ${item.type==='chat'?item.text:item.name}`;});}
function renderReplyBars(){const setup=(sel,id,isHost)=>{const box=$(sel),item=state.chatMessages.find(x=>x.id===id&&!x.deleted);if(!box)return;if(!item){box.classList.add('hidden');box.textContent='';return;}box.classList.remove('hidden');box.textContent='';const sp=document.createElement('span');sp.textContent=`↩ ${item.sender}: ${item.type==='chat'?item.text.slice(0,80):item.name}`;const b=document.createElement('button');b.type='button';b.textContent='✕';b.addEventListener('click',()=>{if(isHost)state.hostReplyTo=null;else state.viewer.replyTo=null;renderReplyBars();});box.append(sp,b);};setup('#hostReplyBar',state.hostReplyTo,true);setup('#viewerReplyBar',state.viewer.replyTo,false);}

function handleChatClick(e,isHost){const btn=e.target.closest('[data-msg-action]');if(!btn)return;const id=btn.dataset.messageId,action=btn.dataset.msgAction,item=state.chatMessages.find(x=>x.id===id);if(!item)return;if(action==='reply'){if(isHost)state.hostReplyTo=id;else state.viewer.replyTo=id;renderReplyBars();(isHost?$('#hostChatInput'):$('#viewerChatInput')).focus();}else if(action==='mention'){const input=isHost?$('#hostChatInput'):$('#viewerChatInput');input.value=`${input.value}${input.value?' ':''}@${item.sender} `;input.focus();}else if(action==='react'){if(isHost)handleMessageReaction('host',id,btn.dataset.emoji);else state.viewer.data?.send({type:'message-react',messageId:id,emoji:btn.dataset.emoji});}else if(action==='delete'){if(isHost)deleteMessage(id);else state.viewer.data?.send({type:'moderation',action:'delete-message',messageId:id});}else if(action==='pin'){if(isHost)pinMessage(id);else state.viewer.data?.send({type:'moderation',action:'pin-message',messageId:id});}}

function handleLiveReaction(p,emoji){if(!['👏','❤️','🔥','😂','👍'].includes(emoji))return;const ts=now();p.reactionTimes=p.reactionTimes.filter(x=>ts-x<3000);p.reactionTimes.push(ts);if(p.reactionTimes.length>8)return;broadcast({type:'live-reaction',emoji,name:p.name});spawnReaction($('#hostReactionLayer'),emoji);}
function spawnReaction(layer,emoji){if(!layer)return;const el=document.createElement('span');el.className='floating-reaction';el.textContent=emoji;el.style.left=`${10+Math.random()*80}%`;layer.append(el);setTimeout(()=>el.remove(),3000);}

function createPoll(question,options){const q=normalizeText(question,120),opts=options.map(x=>normalizeText(x,60)).filter(Boolean).slice(0,6);if(!q||opts.length<2||isSuspicious(q)||opts.some(isSuspicious)){showToast('Anket içeriği geçersiz.');return;}state.poll={id:uid(),question:q,options:opts.map(text=>({text,count:0})),closed:false,createdAt:now()};state.pollVoters.clear();broadcast({type:'poll',poll:publicPoll()});renderPollAll();logMod('Yeni anket başlatıldı');}
function publicPoll(){return state.poll?JSON.parse(JSON.stringify(state.poll)):null;}
function handlePollVote(p,pollId,index){if(!state.poll||state.poll.id!==pollId||state.poll.closed||!state.poll.options[index]||state.pollVoters.has(p.peerId))return;state.pollVoters.set(p.peerId,index);state.poll.options[index].count++;broadcast({type:'poll',poll:publicPoll()});renderPollAll();}
function renderPollAll(){renderPoll($('#hostPoll'),true);renderPoll($('#viewerPoll'),false);}
function renderPoll(box,isHost){if(!box)return;box.textContent='';const poll=state.poll;if(!poll){const s=document.createElement('span');s.className='muted';s.textContent='Aktif anket yok.';box.append(s);return;}const q=document.createElement('div');q.className='poll-question';q.textContent=`📊 ${poll.question}${poll.closed?' • Kapalı':''}`;box.append(q);const total=poll.options.reduce((a,o)=>a+o.count,0);poll.options.forEach((o,i)=>{const row=document.createElement('div');row.className='poll-option';const lbl=document.createElement('span'),pct=document.createElement('b'),bar=document.createElement('div'),fill=document.createElement('i');const pc=total?Math.round(o.count/total*100):0;lbl.textContent=o.text;pct.textContent=`${o.count} • %${pc}`;bar.className='poll-bar';fill.style.width=`${pc}%`;bar.append(fill);row.append(lbl,pct,bar);if(!isHost&&!poll.closed&&state.viewer.pollVoted!==poll.id){const b=document.createElement('button');b.type='button';b.textContent=`Oy ver: ${o.text}`;b.dataset.pollVote=i;row.append(b);}box.append(row);});if(isHost&&!poll.closed){const b=document.createElement('button');b.type='button';b.className='secondary-btn';b.textContent='Anketi Kapat';b.addEventListener('click',()=>{state.poll.closed=true;broadcast({type:'poll',poll:publicPoll()});renderPollAll();logMod('Anket kapatıldı');});box.append(b);}}

function handleModeratorCommand(actor,data){if(actor.role!=='moderator'){securityKick(actor.peerId,'Yetkisiz moderasyon komutu');return;}const action=data.action;if(action==='mute')muteParticipant(data.peerId,actor.name);else if(action==='kick')kickParticipant(data.peerId,`${actor.name} (moderatör) tarafından çıkarıldı`);else if(action==='delete-message')deleteMessage(data.messageId,actor.name);else if(action==='pin-message')pinMessage(data.messageId,actor.name);}
function broadcastModSnapshots(){const snap=[...state.participants.values()].filter(p=>p.admitted).map(p=>({peerId:p.peerId,name:p.name,role:p.role,speaking:p.speaking,raisedHand:p.raisedHand,quality:p.quality,connectedAt:p.connectedAt}));state.dataConnections.forEach((c,id)=>{if(c.open&&state.participants.get(id)?.role==='moderator')c.send({type:'mod-snapshot',items:snap});});}
function renderViewerModPanel(){const panel=$('#viewerModPanel'),box=$('#viewerModParticipants');if(state.viewer.role!=='moderator'){panel.classList.add('hidden');return;}panel.classList.remove('hidden');box.textContent='';state.viewer.modSnapshot.filter(x=>x.peerId!==state.peer?.id).forEach(p=>{const row=document.createElement('div');row.className='participant-row';const a=document.createElement('div');a.className='participant-avatar';a.textContent=p.name.slice(0,2).toUpperCase();const m=document.createElement('div');m.className='participant-meta';const b=document.createElement('b'),s=document.createElement('span');b.textContent=p.name;s.className='participant-status';s.textContent=`${roleLabel(p.role)} • 📶 ${qualityLabel(p.quality)}`;m.append(b,s);const acts=document.createElement('div');acts.className='participant-actions';acts.append(actionBtn('🔇 Sustur','mod-mute',p.peerId,'danger-soft'),actionBtn('⛔ Çıkar','mod-kick',p.peerId,'danger-soft'));row.append(a,m,acts);box.append(row);});}

function startTimers(){clearInterval(state.timer);state.timer=setInterval(()=>{if(state.startedAt)$('#elapsed').textContent=fmtTime(now()-state.startedAt);if(state.viewer.connectedAt)$('#viewerDuration').textContent=fmtTime(now()-state.viewer.connectedAt);pollAudioLevels();},1000);clearInterval(state.qualityTimer);state.qualityTimer=setInterval(updateQuality,5000);clearInterval(state.renderTimer);state.renderTimer=setInterval(()=>{if(!studioView.classList.contains('hidden')){renderParticipants();renderSpeakerQueue();}},5000);}
async function updateQuality(){for(const [id,call]of state.calls){const p=state.participants.get(id),pc=call.peerConnection;if(!p||!pc)continue;try{const stats=await pc.getStats();let rtt=null,loss=0,bytes=null;stats.forEach(r=>{if(r.type==='candidate-pair'&&r.state==='succeeded'&&r.currentRoundTripTime!=null)rtt=r.currentRoundTripTime;if(r.type==='remote-inbound-rtp'&&r.kind==='video'&&r.fractionLost!=null)loss=Math.max(loss,r.fractionLost);if(r.type==='outbound-rtp'&&r.kind==='video')bytes=r.bytesSent;});let bitrate='';if(bytes!=null){const ts=now();if(p.lastBytesAt){bitrate=`${Math.max(0,Math.round((bytes-p.lastBytes)*8/(ts-p.lastBytesAt)))} kbps`;}p.lastBytes=bytes;p.lastBytesAt=ts;}p.quality=(rtt>0.35||loss>.08)?'bad':(rtt>0.15||loss>.03)?'mid':'good';p.qualityDetail=[rtt!=null?`${Math.round(rtt*1000)}ms`:'',bitrate].filter(Boolean).join(' ');}catch{}}renderParticipants();broadcastModSnapshots();if(state.viewer.call?.peerConnection){try{const stats=await state.viewer.call.peerConnection.getStats();let rtt=null;stats.forEach(r=>{if(r.type==='candidate-pair'&&r.state==='succeeded'&&r.currentRoundTripTime!=null)rtt=r.currentRoundTripTime;});state.viewer.quality=rtt==null?'—':rtt>.35?'bad':rtt>.15?'mid':'good';$('#viewerQuality').textContent=`📶 ${qualityLabel(state.viewer.quality)}${rtt!=null?` ${Math.round(rtt*1000)}ms`:''}`;$('#viewerQuality').className=`quality-badge ${qualityClass(state.viewer.quality)}`;}catch{}}}

function createPauseStream(){const c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=1280;c.height=720;ctx.fillStyle='#06101d';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#fff';ctx.font='bold 52px sans-serif';ctx.textAlign='center';ctx.fillText('⏸ YAYIN DURAKLATILDI',640,335);ctx.font='28px sans-serif';ctx.fillStyle='#9eb0c8';ctx.fillText('Yayın birazdan devam edecek',640,390);return c.captureStream(1);}
async function togglePause(){state.paused=!state.paused;if(state.paused){state.pauseMedia=createPauseStream();const video=state.pauseMedia.getVideoTracks()[0];for(const call of state.calls.values()){const s=call.peerConnection?.getSenders?.().find(x=>x.track?.kind==='video');if(s)await s.replaceTrack(video).catch(()=>{});}broadcast({type:'pause',paused:true});$('#pauseBanner').classList.remove('hidden');$('#pauseBtn').classList.add('live');logMod('Yayın duraklatıldı');}else{state.pauseMedia?.getTracks().forEach(x=>x.stop());state.pauseMedia=null;await applyOutgoingStreams(state.currentBroadcastStream||state.localStream,state.stagePeerId);broadcast({type:'pause',paused:false});$('#pauseBanner').classList.add('hidden');$('#pauseBtn').classList.remove('live');logMod('Yayın devam ettirildi');}}
function toggleRecording(){if(state.recording?.state==='recording'){state.recording.stop();return;}const stream=state.currentBroadcastStream||state.localStream;if(!stream||!window.MediaRecorder){showToast('Kayıt desteklenmiyor.');return;}try{state.recordChunks=[];const rec=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm'});rec.ondataavailable=e=>{if(e.data.size)state.recordChunks.push(e.data);};rec.onstop=()=>{const blob=new Blob(state.recordChunks,{type:'video/webm'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ebs-live-${new Date().toISOString().replace(/[:.]/g,'-')}.webm`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#recordBtn').classList.remove('live');$('#recordState').textContent='Kapalı';logMod('Yayın kaydı tamamlandı');};rec.start(1000);state.recording=rec;$('#recordBtn').classList.add('live');$('#recordState').textContent='Kayıtta';logMod('Yayın kaydı başlatıldı');}catch(e){console.error(e);showToast('Kayıt başlatılamadı.');}}
function screenshot(){const c=document.createElement('canvas');c.width=1280;c.height=720;const ctx=c.getContext('2d');if(state.stageComposite?.canvas)ctx.drawImage(state.stageComposite.canvas,0,0,c.width,c.height);else drawCover(ctx,localVideo,0,0,c.width,c.height);c.toBlob(blob=>{if(!blob)return;const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`ebs-live-shot-${Date.now()}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(u),20000);},'image/png');}
function toggleHostMic(){const tracks=state.localStream?.getAudioTracks?.()||[];if(!tracks.length){showToast('Yayıncı mikrofon izi yok.');return;}const enabled=!tracks[0].enabled;tracks.forEach(x=>x.enabled=enabled);$('#toggleMicBtn').classList.toggle('off',!enabled);showToast(enabled?'Mikrofon açıldı':'Mikrofon kapatıldı');}

function cleanupAllMedia(){state.recording?.state==='recording'&&state.recording.stop();state.calls.forEach(c=>c.close());state.dataConnections.forEach(c=>c.close());state.peer?.destroy?.();state.localStream?.getTracks().forEach(x=>x.stop());state.rawStreams.forEach(s=>s.getTracks().forEach(x=>x.stop()));state.audioContexts.forEach(c=>c.close?.().catch(()=>{}));state.viewerAudioEls.forEach(a=>a.remove());state.analysers.forEach(a=>a.ctx.close().catch(()=>{}));stopStageComposite();state.pauseMedia?.getTracks?.().forEach(x=>x.stop());state.rawStreams=[];state.audioContexts=[];state.calls.clear();state.dataConnections.clear();state.participants.clear();state.viewerAudioEls.clear();state.analysers.clear();state.screenStream=null;state.screenVideoEl=null;}

async function switchScreenSource(){if(state.source!=='screen'||!state.localStream){showToast('Ekran değiştirme yalnızca ekran paylaşımında kullanılabilir.');return;}if(state.paused){showToast('Yayın duraklatılırken ekran değiştirilemez.');return;}const btn=$('#switchScreenBtn');if(btn)btn.disabled=true;try{const newDisplay=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:{ideal:30,max:60}},audio:true});const newTrack=newDisplay.getVideoTracks()[0];if(!newTrack){newDisplay.getTracks().forEach(x=>x.stop());return;}newTrack.addEventListener('ended',stopBroadcast);if(state.screenVideoEl){const old=state.screenStream;state.screenVideoEl.srcObject=newDisplay;await state.screenVideoEl.play().catch(()=>{});state.screenStream=newDisplay;state.rawStreams.push(newDisplay);if(old){old.getTracks().forEach(x=>x.stop());state.rawStreams=state.rawStreams.filter(s=>s!==old);}}else{const oldTrack=state.localStream.getVideoTracks()[0];state.localStream.removeTrack(oldTrack);state.localStream.addTrack(newTrack);localVideo.srcObject=state.localStream;oldTrack.stop();newDisplay.getAudioTracks().forEach(x=>x.stop());if(!state.stagePeerId)await applyOutgoingStreams(state.localStream,null);}logMod('Ekran kaynağı değiştirildi');showToast('Ekran kaynağı değiştirildi');}catch(err){if(err.name!=='NotAllowedError')showToast('Ekran değiştirilemedi: '+(err.message||err.name));}finally{if(btn)btn.disabled=false;}}
function stopBroadcast(){clearInterval(state.timer);clearInterval(state.qualityTimer);clearInterval(state.renderTimer);broadcast({type:'broadcast-ended'},false);cleanupAllMedia();studioView.classList.add('hidden');homeView.classList.remove('hidden');features.classList.remove('hidden');shareLink.value='Bağlantı hazırlanıyor…';$('#qrCode').textContent='';$('#startBtn').disabled=false;setNetwork(t('ready'));showToast('Yayın sonlandırıldı');}

function createViewerOfferStream(){const stream=new MediaStream(),canvas=document.createElement('canvas');canvas.width=2;canvas.height=2;const ctx=canvas.getContext('2d');ctx.fillStyle='#000';ctx.fillRect(0,0,2,2);const cs=canvas.captureStream(1),vt=cs.getVideoTracks()[0];if(vt)stream.addTrack(vt);const AC=window.AudioContext||window.webkitAudioContext;let ac=null,osc=null;if(AC){try{ac=new AC();const dest=ac.createMediaStreamDestination(),gain=ac.createGain();gain.gain.value=0;osc=ac.createOscillator();osc.connect(gain);gain.connect(dest);osc.start();const at=dest.stream.getAudioTracks()[0];if(at)stream.addTrack(at);}catch{}}return{stream,cleanup(){stream.getTracks().forEach(x=>x.stop());try{osc?.stop();}catch{}ac?.close?.().catch(()=>{});}};}

function initViewer(id){document.querySelector('meta[name="robots"]')?.setAttribute('content','noindex,nofollow');document.title='Özel Yayın — EBS Live';homeView.classList.add('hidden');features.classList.add('hidden');viewerView.classList.remove('hidden');$('.site-header').classList.add('hidden');if(!state.viewer.name){$('#nameGate').classList.remove('hidden');setTimeout(()=>$('#viewerNameInput').focus(),80);return;}connectViewer(id);}
function connectViewer(hostId){if(!window.Peer){viewerError('PeerJS yüklenemedi.');return;}state.peer=new Peer(undefined,{debug:1});state.peer.on('open',()=>{setupViewerData(hostId);startTimers();});state.peer.on('error',err=>{console.error(err);viewerError(err.type==='peer-unavailable'?'Yayıncı çevrimdışı.':'P2P bağlantısı kurulamadı.');});}
function setupViewerData(hostId){const conn=state.peer.connect(hostId,{reliable:true});state.viewer.data=conn;conn.on('open',()=>{conn.send({type:'hello',name:state.viewer.name,pin:state.viewer.pin});$('#lobbyGate').classList.remove('hidden');$('#lobbyTitle').textContent=t('waiting');});conn.on('data',data=>handleViewerData(hostId,data));conn.on('close',()=>{if(state.viewer.admitted)viewerError('Kontrol bağlantısı kapandı.');});conn.on('error',()=>viewerError('Kontrol bağlantısı kurulamadı.'));}
function handleViewerData(hostId,data){if(!data||typeof data!=='object')return;
 if(data.type==='host-ready'){$('#lobbyTitle').textContent=data.locked?t('locked'):t('waiting');
 }else if(data.type==='lobby-pending'){$('#lobbyGate').classList.remove('hidden');$('#lobbyTitle').textContent=t('waiting');$('#lobbyText').textContent='Katılma isteğiniz yayıncıya gönderildi.';
 }else if(data.type==='admitted'){state.viewer.admitted=true;state.viewer.role=data.role||'viewer';state.viewer.connectedAt=now();state.chatMessages=Array.isArray(data.history)?data.history:[];state.pinnedMessageId=data.pinnedId||null;state.poll=data.poll||null;$('#lobbyGate').classList.add('hidden');$('#viewerRoleBadge').textContent=roleLabel(state.viewer.role);renderViewerModPanel();renderChatAll();renderPollAll();startViewerCall(hostId);showToast(t('admitted'));
 }else if(data.type==='rejected'){$('#lobbyTitle').textContent=t('rejected');$('#lobbyText').textContent=normalizeText(data.reason,180);showToast(data.reason||t('rejected'));
 }else if(data.type==='kicked'){forceViewerMediaOff();viewerError(`Oturumdan çıkarıldınız: ${normalizeText(data.reason,160)}`);
 }else if(data.type==='mic-approved'){state.viewer.micAllowed=true;$('#viewerMicBtn').classList.remove('hidden');showToast('Mikrofon izni verildi.');
 }else if(data.type==='mic-disable'){state.viewer.micAllowed=false;forceViewerMicOff();$('#viewerMicBtn').classList.add('hidden');showToast('Mikrofon yayıncı/moderatör tarafından kapatıldı.');
 }else if(data.type==='camera-approved'){state.viewer.camAllowed=true;$('#viewerCameraBtn').classList.remove('hidden');showToast('Kamera izni verildi.');
 }else if(data.type==='role'){state.viewer.role=data.role||'viewer';$('#viewerRoleBadge').textContent=roleLabel(state.viewer.role);renderViewerModPanel();renderChatAll();
 }else if(data.type==='history'){state.chatMessages=Array.isArray(data.items)?data.items:[];renderChatAll();
 }else if(data.type==='chat-item'){state.chatMessages.push(data.item);if(state.chatMessages.length>120)state.chatMessages.shift();renderChatAll();
 }else if(data.type==='chat-update'){const i=state.chatMessages.findIndex(x=>x.id===data.item?.id);if(i>=0)state.chatMessages[i]=data.item;renderChatAll();
 }else if(data.type==='chat-delete'){const x=state.chatMessages.find(m=>m.id===data.id);if(x)x.deleted=true;renderChatAll();
 }else if(data.type==='chat-pin'){state.pinnedMessageId=data.id||null;renderPinned();renderChatAll();
 }else if(data.type==='live-reaction'){spawnReaction($('#viewerReactionLayer'),data.emoji);
 }else if(data.type==='poll'){state.poll=data.poll||null;renderPollAll();
 }else if(data.type==='pause'){$('#viewerPauseBanner').classList.toggle('hidden',!data.paused);
 }else if(data.type==='stage-state'){showToast(data.active?`${data.name} sahneye alındı`:'Konuk sahneden ayrıldı');
 }else if(data.type==='temp-muted'){showToast(`Anti-spam: ${Math.ceil((data.until-now())/1000)} sn mesaj gönderemezsiniz.`);
 }else if(data.type==='mod-snapshot'){state.viewer.modSnapshot=Array.isArray(data.items)?data.items:[];renderViewerModPanel();
 }else if(data.type==='broadcast-ended'){viewerError('Yayın sona erdi.');}}

function startViewerCall(hostId){const offer=createViewerOfferStream();state.viewer.offer=offer;const call=state.peer.call(hostId,offer.stream);state.viewer.call=call;if(!call){viewerError('Medya çağrısı başlatılamadı.');return;}let got=false;const timeout=setTimeout(()=>{if(!got)viewerError('Yayın akışı alınamadı.');},15000);call.on('stream',stream=>{got=true;clearTimeout(timeout);remoteVideo.srcObject=stream;$('#remotePlaceholder').classList.add('hidden');$('#viewerStatus').innerHTML='<i></i> Canlı yayın';remoteVideo.play().catch(()=>showToast('Videoyu başlatmak için ekrana dokunun.'));});call.on('close',()=>viewerError('Yayın bağlantısı kapandı.'));call.on('error',()=>viewerError('Yayın bağlantısı kesildi.'));}
function viewerError(message){$('#viewerStatus').innerHTML='<i style="background:#ff4964"></i> Bağlantı yok';$('#remotePlaceholder').classList.remove('hidden');$('#remotePlaceholder h1').textContent=message;$('#remotePlaceholder p').textContent='Bağlantıyı kontrol edin veya yeni davet bağlantısı isteyin.';}

function raiseHand(){if(!state.viewer.admitted||!state.viewer.data?.open)return;state.viewer.hand=!state.viewer.hand;state.viewer.data.send({type:state.viewer.hand?'raise-hand':'cancel-hand'});$('#raiseHandBtn').textContent=state.viewer.hand?t('cancelHand'):t('raise');$('#talkTitle').textContent=state.viewer.hand?'Söz isteğin gönderildi':'Yayına katıl';}
async function toggleViewerMic(){if(!state.viewer.micAllowed){showToast('Yayıncı mikrofon izni vermedi.');return;}const existing=state.viewer.micStream?.getAudioTracks?.()[0];if(existing?.readyState==='live'){existing.enabled=!existing.enabled;state.viewer.data?.send({type:existing.enabled?'mic-enabled':'mic-disabled'});$('#viewerMicBtn').textContent=existing.enabled?t('micClose'):t('micOpen');return;}try{const ms=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false}),track=ms.getAudioTracks()[0],sender=state.viewer.call?.peerConnection?.getSenders?.().find(s=>s.track?.kind==='audio');if(!track||!sender)throw new Error('audio sender missing');await sender.replaceTrack(track);state.viewer.micStream=ms;track.enabled=true;track.addEventListener('ended',()=>state.viewer.data?.send({type:'mic-disabled'}));state.viewer.data?.send({type:'mic-enabled'});$('#viewerMicBtn').textContent=t('micClose');}catch(err){console.error(err);showToast(err.name==='NotAllowedError'?'Mikrofon izni verilmedi.':'Mikrofon açılamadı.');}}
function forceViewerMicOff(){const tr=state.viewer.micStream?.getAudioTracks?.()[0];if(tr)tr.enabled=false;state.viewer.data?.send({type:'mic-disabled'});$('#viewerMicBtn').textContent=t('micOpen');}
async function toggleViewerCamera(){if(!state.viewer.camAllowed){showToast('Yayıncı kamera izni vermedi.');return;}const existing=state.viewer.camStream?.getVideoTracks?.()[0];if(existing?.readyState==='live'){existing.enabled=!existing.enabled;state.viewer.data?.send({type:existing.enabled?'camera-enabled':'camera-disabled'});$('#viewerCameraBtn').textContent=existing.enabled?t('camClose'):t('camOpen');return;}try{const ms=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},facingMode:'user'},audio:false}),track=ms.getVideoTracks()[0],sender=state.viewer.call?.peerConnection?.getSenders?.().find(s=>s.track?.kind==='video');if(!track||!sender)throw new Error('video sender missing');await sender.replaceTrack(track);state.viewer.camStream=ms;track.enabled=true;track.addEventListener('ended',()=>state.viewer.data?.send({type:'camera-disabled'}));state.viewer.data?.send({type:'camera-enabled'});$('#viewerCameraBtn').textContent=t('camClose');}catch(err){console.error(err);showToast(err.name==='NotAllowedError'?'Kamera izni verilmedi.':'Kamera açılamadı.');}}
function forceViewerMediaOff(){forceViewerMicOff();state.viewer.camStream?.getTracks?.().forEach(x=>x.stop());state.viewer.micStream?.getTracks?.().forEach(x=>x.stop());state.viewer.offer?.cleanup?.();state.viewer.call?.close?.();}

const EMOJIS=['😀','😂','😍','🥰','😎','🤔','👏','👍','👎','❤️','🔥','🎉','🙏','💯','😮','😢','😡','✅','🚀','📌','💡'];
function setupEmojiPickers(){$$('[data-emoji-target]').forEach(btn=>{const input=$(`#${btn.dataset.emojiTarget}`),picker=btn.closest('.chat-card')?.querySelector('.emoji-picker');if(!input||!picker)return;picker.textContent='';EMOJIS.forEach(em=>{const b=document.createElement('button');b.type='button';b.textContent=em;b.addEventListener('click',()=>{input.value=(input.value+em).slice(0,500);picker.classList.add('hidden');input.focus();});picker.append(b);});btn.addEventListener('click',()=>picker.classList.toggle('hidden'));});}

$('#nameGateForm').addEventListener('submit',e=>{e.preventDefault();const name=safeName($('#viewerNameInput').value),pin=safePin($('#viewerPinInput').value);if(!name){showToast('Geçerli bir ad girin. Script/XSS/HTML kabul edilmez.');return;}if(pin===null){showToast('PIN 4-8 rakam olmalı.');return;}state.viewer.name=name;state.viewer.pin=pin;$('#viewerNameBadge').textContent=name;$('#nameGate').classList.add('hidden');connectViewer(watchId);});
$('#startBtn').addEventListener('click',startBroadcast);$('#stopBtn').addEventListener('click',stopBroadcast);$('#toggleMicBtn').addEventListener('click',toggleHostMic);$('#switchScreenBtn')?.addEventListener('click',switchScreenSource);$('#copyBtn').addEventListener('click',copyLink);$('#pauseBtn').addEventListener('click',togglePause);$('#recordBtn').addEventListener('click',toggleRecording);$('#shotBtn').addEventListener('click',screenshot);$('#lockBtn').addEventListener('click',()=>{state.settings.locked=!state.settings.locked;updateSecurityText();logMod(state.settings.locked?'Yayın yeni katılımcılara kilitlendi':'Yayın kilidi açıldı');});
$('#participantsList').addEventListener('click',e=>{const b=e.target.closest('[data-action][data-peer]');if(!b)return;const {action,peer}=b.dataset;if(action==='approve-mic')approveMic(peer);else if(action==='mute')muteParticipant(peer);else if(action==='approve-camera')approveCamera(peer);else if(action==='stage')stageParticipant(peer);else if(action==='unstage')removeFromStage(peer);else if(action==='kick')kickParticipant(peer);});
$('#participantsList').addEventListener('change',e=>{const s=e.target.closest('select[data-action="role"]');if(s)setRole(s.dataset.peer,s.value);});
$('#waitingList').addEventListener('click',e=>{const b=e.target.closest('[data-action][data-peer]');if(!b)return;b.dataset.action==='approve-wait'?approveAdmission(b.dataset.peer):rejectAdmission(b.dataset.peer);});
$('#speakerQueue').addEventListener('click',e=>{const b=e.target.closest('[data-action="approve-mic"]');if(b)approveMic(b.dataset.peer);});
$('#raiseHandBtn').addEventListener('click',raiseHand);$('#viewerMicBtn').addEventListener('click',toggleViewerMic);$('#viewerCameraBtn').addEventListener('click',toggleViewerCamera);$('#fullscreenBtn').addEventListener('click',()=>{const target=$('#viewerStage');document.fullscreenElement?document.exitFullscreen?.():target.requestFullscreen?.();});
$('#liveReactionButtons').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!state.viewer.data?.open)return;state.viewer.data.send({type:'live-reaction',emoji:b.textContent});spawnReaction($('#viewerReactionLayer'),b.textContent);});
$('#hostChatForm').addEventListener('submit',e=>{e.preventDefault();sendHostMessage($('#hostChatInput').value);$('#hostChatInput').value='';});
$('#viewerChatForm').addEventListener('submit',e=>{e.preventDefault();const input=$('#viewerChatInput'),text=normalizeText(input.value,500);if(!text)return;state.viewer.data?.send({type:'chat',text,replyTo:state.viewer.replyTo});state.viewer.replyTo=null;input.value='';renderReplyBars();});
$('#hostFileInput').addEventListener('change',async e=>{const f=e.target.files?.[0];if(f)await sendFile(f,true);e.target.value='';});$('#viewerFileInput').addEventListener('change',async e=>{const f=e.target.files?.[0];if(f)await sendFile(f,false);e.target.value='';});
$('#hostChatMessages').addEventListener('click',e=>handleChatClick(e,true));$('#viewerChatMessages').addEventListener('click',e=>handleChatClick(e,false));
$('#pollForm').addEventListener('submit',e=>{e.preventDefault();createPoll($('#pollQuestion').value,$('#pollOptions').value.split(','));});$('#viewerPoll').addEventListener('click',e=>{const b=e.target.closest('[data-poll-vote]');if(!b||!state.poll)return;state.viewer.data?.send({type:'poll-vote',pollId:state.poll.id,option:Number(b.dataset.pollVote)});state.viewer.pollVoted=state.poll.id;renderPollAll();});
$('#viewerModParticipants').addEventListener('click',e=>{const b=e.target.closest('[data-action][data-peer]');if(!b)return;const action=b.dataset.action==='mod-mute'?'mute':'kick';state.viewer.data?.send({type:'moderation',action,peerId:b.dataset.peer});});
$('#mobileChatBtn').addEventListener('click',()=>$('#viewerChatCard').classList.add('mobile-open'));$('#closeMobileChatBtn').addEventListener('click',()=>$('#viewerChatCard').classList.remove('mobile-open'));
setupEmojiPickers();renderModLog();renderChatAll();renderPollAll();renderWaiting();renderSpeakerQueue();
addEventListener('beforeunload',()=>{forceViewerMediaOff();cleanupAllMedia();});
if(watchId&&/^[A-Za-z0-9_-]{1,128}$/.test(watchId))initViewer(watchId);
})();
